        "emotional_tone": "甜爽、疑惑、温柔",
        "key_scenes": ["副本挑战", "女主的怀疑", "男主的安抚"]
      },
      {
        "chapter_number": 6,
        "chapter_title": "警告",
        "core_event": "第六个副本，系统管理员出现，警告男主不要打破规则，男主坚定守护女主的决心。",
        "emotional_tone": "紧张、坚定、守护",
        "key_scenes": ["副本挑战", "系统管理员出现", "男主的决心"]
      },
      {
        "chapter_number": 7,
        "chapter_title": "准备",
        "core_event": "第七个副本，男主积累实力和资源，准备在第八个副本打破规则，让女主真正复活。",
        "emotional_tone": "紧张、准备、决心",
        "key_scenes": ["副本挑战", "积累实力", "准备决战"]
      }
